const app=document.querySelector('#app'),money=n=>'£'+Math.round(n).toLocaleString('en-GB'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
